design.compositionCss:
/* Blue Note: original cut-paper screening dossier. */
.shell{grid-template-columns:210px minmax(0,1fr)}
.sidebar{padding:24px 14px;border-right:14px solid var(--acid)}
.brand{padding:8px 8px 22px;border-bottom:6px solid var(--weekly-mark)}
.sidebar nav{display:grid;grid-template-columns:1fr;gap:8px}
.nav-item{min-height:52px;border:1px dashed var(--acid);border-left:11px solid var(--weekly-mark);padding:9px 11px;transform:rotate(-.35deg);font-size:12px}
.nav-item:nth-child(even){transform:rotate(.35deg)}
.nav-item span{font-family:var(--condensed);font-size:25px;min-width:29px}
main{max-width:1720px;padding:0 3.5vw 84px}
.topbar{min-height:155px;border-bottom:4px solid var(--ink);padding:32px 0}
.topbar h1{font-family:var(--display);font-size:clamp(48px,6vw,88px);line-height:.88;letter-spacing:-.075em;max-width:980px}
.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr));gap:14px}
.poster-focus{grid-column:1/-1;min-height:640px;padding:48px 42px;border:0;border-left:24px solid var(--acid);border-bottom:16px solid var(--weekly-mark)}
.poster-focus h2{font-family:var(--display);font-size:clamp(86px,10.5vw,158px);line-height:.82;letter-spacing:-.085em;max-width:850px}
.poster-focus h2 span{width:fit-content;border-bottom:10px solid var(--weekly-mark);transform:rotate(-1deg)}
.poster-focus .hero-script{font-size:36px!important;max-width:570px;transform:rotate(-2deg)}
.poster-focus .cinema-scene{width:51%;right:-5%;top:12%;transform:rotate(7deg) scale(1.08);opacity:.48}
.hero-grid .stat-card{grid-column:auto;min-height:150px;display:block;border:1px solid var(--ink);border-top:12px solid var(--weekly-mark);padding:20px;background:var(--panel);box-shadow:7px 7px 0 var(--weekly-soft);transform:rotate(-.5deg)}
.hero-grid .stat-card:nth-child(even){transform:rotate(.5deg)}
.hero-grid .stat-card strong{font-family:var(--display);font-size:57px;line-height:.9;display:block;margin:10px 0}
.studio-programme{grid-template-columns:repeat(3,minmax(0,1fr));gap:14px;border:0}
.studio-programme button{min-height:118px;border:1px dashed var(--ink)!important;border-left:12px solid var(--weekly-mark)!important;padding:22px!important;background:var(--panel);box-shadow:5px 5px 0 var(--weekly-soft)}
.studio-programme span{font-family:var(--display);font-size:25px;letter-spacing:-.04em}
.panel h2,.intro-panel h2,.module h3{font-family:var(--display);letter-spacing:-.06em}
.syllabus-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:25px}
.module{border:1px solid var(--ink);border-top:14px solid var(--weekly-mark);padding:27px;box-shadow:8px 8px 0 var(--weekly-soft);transform:rotate(-.45deg)}
.module:nth-child(even){transform:rotate(.45deg);margin-top:28px}
.module h3{font-size:34px}
.roadmap{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:22px;columns:auto}
.phase{min-height:245px;margin:0!important;border:1px solid var(--ink);border-left:18px solid var(--weekly-mark);padding:28px;background:var(--panel);box-shadow:6px 6px 0 var(--weekly-soft);transform:rotate(-.4deg)}
.phase:nth-child(even){transform:rotate(.4deg);margin-top:34px!important}
.phase h3{font-family:var(--display);font-size:32px;letter-spacing:-.055em}
.resource-list{gap:20px}
.resource{grid-template-columns:minmax(0,1.3fr) minmax(0,1fr) auto;border:1px solid var(--ink);border-left:16px solid var(--weekly-mark);padding:24px;box-shadow:6px 6px 0 var(--weekly-soft);transform:rotate(-.25deg)}
.resource:nth-child(even){transform:rotate(.25deg)}
.resource h3{font-family:var(--display);font-size:21px;letter-spacing:-.04em}
.evidence-grid{grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}
.evidence-card{border:1px dashed var(--ink);border-top:12px solid var(--weekly-mark);padding:24px;box-shadow:5px 5px 0 var(--weekly-soft)}
.cinema-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}
.cinema-film{border:1px solid var(--ink);padding:23px;box-shadow:7px 7px 0 var(--weekly-soft);transform:rotate(-.35deg)}
.cinema-film:nth-child(even){transform:rotate(.35deg)}
.film-cover{min-height:355px;border:2px solid var(--ink);border-bottom:14px solid var(--weekly-mark)}
.cinema-film .film-cover h3{font-family:var(--display);font-size:54px;line-height:.94;letter-spacing:-.065em}
.journal-masthead{border-bottom:8px solid var(--ink);padding-bottom:38px}
.journal-masthead h2{font-family:var(--display);font-size:clamp(88px,11vw,158px);line-height:.84;letter-spacing:-.085em}
.journal-masthead h2 em{font-family:var(--script);font-size:.78em}
.journal-workbench{grid-template-columns:minmax(0,1.2fr) minmax(280px,.8fr);gap:30px}
.journal-deck{grid-template-columns:repeat(2,minmax(0,1fr));gap:26px}
.diary-card:nth-child(n){margin:0;transform:rotate(-.45deg);border:1px solid var(--ink);border-left:14px solid var(--weekly-mark);padding:27px;box-shadow:8px 8px 0 var(--weekly-soft)}
.diary-card:nth-child(even){transform:rotate(.45deg)}
.diary-card h3{font-family:var(--display);font-size:54px;line-height:.94;letter-spacing:-.065em}
@media(max-width:1100px) and (min-width:761px){.shell{grid-template-columns:185px minmax(0,1fr)}.poster-focus h2{font-size:105px}.roadmap{grid-template-columns:1fr}.phase:nth-child(n){margin:0!important}.evidence-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:760px){.shell{display:block}.sidebar{display:block;border-right:0;border-bottom:10px solid var(--acid);padding:18px 20px}.hero-grid:not(.daily-summary){grid-template-columns:repeat(3,minmax(0,1fr));gap:8px}.poster-focus{grid-column:1/-1;min-height:520px;padding:30px 22px;border-left:10px solid var(--acid);border-bottom:10px solid var(--weekly-mark)}.poster-focus h2{font-size:clamp(68px,18vw,98px);line-height:.87}.poster-focus h2 span{border-bottom-width:6px;transform:none}.poster-focus .hero-script{font-size:27px!important;transform:none}.poster-focus .cinema-scene{width:72%;right:-14%;opacity:.3}.hero-grid .stat-card{min-height:125px;padding:14px 9px;transform:none;box-shadow:3px 3px 0 var(--weekly-soft)}.hero-grid .stat-card strong{font-size:36px}.studio-programme{grid-template-columns:1fr;gap:13px}.studio-programme button{min-height:94px}.syllabus-grid,.roadmap,.cinema-grid,.journal-deck,.evidence-grid{grid-template-columns:1fr;gap:20px}.module:nth-child(n),.phase:nth-child(n),.resource:nth-child(n),.cinema-film:nth-child(n),.diary-card:nth-child(n){transform:none;margin:0!important}.module,.phase,.resource,.cinema-film,.diary-card:nth-child(n){padding:22px;box-shadow:4px 4px 0 var(--weekly-soft)}.phase{min-height:0}.resource{display:block}.film-cover{min-height:300px}.cinema-film .film-cover h3{font-size:43px}.journal-masthead h2{font-size:clamp(62px,17vw,94px)}.journal-workbench{grid-template-columns:1fr}.diary-card h3{font-size:43px}}
@media(max-width:400px){.topbar h1{font-size:45px}.poster-focus h2{font-size:64px}.hero-grid .stat-card strong{font-size:32px}.journal-masthead h2{font-size:59px}}
@media(max-width:760px){#view-journal .journal-deck{grid-template-columns:minmax(0,1fr);width:100%}#view-journal .diary-card:nth-child(n){max-width:100%;box-shadow:none}}
